sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({ api, event, helpers, imports }) {
    console.log(event.payload.value, 'Event Payloads'); // Debugging payload
    console.log('api search term',api)
    let searchValue = event.payload.value || event.payload.selectedValue; // Handle both search and select input
    console.log('searched value:',searchValue);
    if (searchValue) {
        console.log("Setting state with:", searchValue);
        api.setState('searchTerm', searchValue);
    }

    console.log("Updated state:", api.state.searchTerm);
}
